//go:build linux

// Copyright 2026 Кислов Роман Сергеевич
// SPDX-License-Identifier: Apache-2.0
package transport

import (
	"errors"
	"net"
	"os"
	"sync"
	"sync/atomic"
	"time"

	"github.com/miekg/dns"
	"golang.org/x/net/ipv4"
	"golang.org/x/net/ipv6"
	"golang.org/x/sys/unix"
)

// Receive only packets already available. ReadBatch does not wait to fill a
// batch on Go's nonblocking socket. The DNS parser and TSIG verifier are still
// provided by miekg/dns; this adapter only amortizes recvmsg system calls.
const udpReadBatchSize = 16

type udpPacketPeer struct {
	grouped      bool
	addr         *net.UDPAddr
	replyControl []byte
	control      [64]byte
}

func (p *udpPacketPeer) Network() string { return "udp" }
func (p *udpPacketPeer) String() string  { return p.addr.String() }

type batchUDPConn struct {
	readSingle                      bool
	enqueueMu                       sync.RWMutex
	writerOnce                      sync.Once
	writes                          chan *udpWriteRequest
	closing, writerStop, writerDone chan struct{}
	epoch                           time.Time
	*net.UDPConn
	reader      *ipv4.PacketConn
	mu          sync.Mutex
	messages    [udpReadBatchSize]ipv4.Message
	data        [udpReadBatchSize][1232]byte
	control     [udpReadBatchSize][128]byte
	next, count int
	closed      atomic.Bool
	deadline    atomic.Int64
}

func (c *batchUDPConn) Close() error {
	if !c.closed.CompareAndSwap(false, true) {
		return net.ErrClosed
	}
	close(c.closing)
	err := c.UDPConn.Close()
	// All producers must finish their enqueue decision before the writer drains.
	c.enqueueMu.Lock()
	close(c.writerStop)
	c.writerOnce.Do(func() { go c.writeLoop() })
	c.enqueueMu.Unlock()
	<-c.writerDone
	return err
}
func (c *batchUDPConn) SetReadDeadline(t time.Time) error {
	d := int64(0)
	if !t.IsZero() {
		d = t.Sub(c.epoch).Nanoseconds()
		if d == 0 {
			d = -1
		}
	}
	c.deadline.Store(d)
	return c.UDPConn.SetReadDeadline(t)
}
func (c *batchUDPConn) SetDeadline(t time.Time) error {
	if err := c.SetReadDeadline(t); err != nil {
		return err
	}
	return c.UDPConn.SetWriteDeadline(t)
}

func wrapUDPPacketConn(conn net.PacketConn) net.PacketConn {
	udp, ok := conn.(*net.UDPConn)
	if !ok {
		return conn
	}
	v4 := ipv4.NewPacketConn(udp)
	err4 := v4.SetControlMessage(ipv4.FlagDst|ipv4.FlagInterface, true)
	err6 := ipv6.NewPacketConn(udp).SetControlMessage(ipv6.FlagDst|ipv6.FlagInterface, true)
	if err4 != nil && err6 != nil {
		return conn
	}
	c := &batchUDPConn{UDPConn: udp, reader: v4, epoch: time.Now(), writes: make(chan *udpWriteRequest, 128), closing: make(chan struct{}), writerStop: make(chan struct{}), writerDone: make(chan struct{})}
	for i := range c.messages {
		c.messages[i].Buffers = [][]byte{c.data[i][:]}
		c.messages[i].OOB = c.control[i][:]
	}
	return c
}

func (c *batchUDPConn) ReadFrom(b []byte) (int, net.Addr, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.closed.Load() {
		return 0, nil, net.ErrClosed
	}
	if d := c.deadline.Load(); d != 0 && time.Since(c.epoch).Nanoseconds() >= d {
		return 0, nil, &net.OpError{Op: "read", Net: "udp", Err: os.ErrDeadlineExceeded}
	}
	if c.next == c.count {
		n := 0
		var err error
		if !c.readSingle {
			n, err = c.reader.ReadBatch(c.messages[:], 0)
			if errors.Is(err, unix.ENOSYS) || errors.Is(err, unix.EOPNOTSUPP) || errors.Is(err, unix.EPERM) {
				c.readSingle = true
			}
		}
		if c.readSingle {
			m := &c.messages[0]
			var addr *net.UDPAddr
			m.N, m.NN, m.Flags, addr, err = c.UDPConn.ReadMsgUDP(c.data[0][:], c.control[0][:])
			m.Addr = addr
			n = 1
		}
		if err != nil {
			return 0, nil, err
		}
		c.next, c.count = 0, n
	}
	m := &c.messages[c.next]
	c.next++
	// The library owns the returned payload buffer and peer independently of
	// the next batch. Neither can reference the reusable receive slots.
	peer := &udpPacketPeer{addr: m.Addr.(*net.UDPAddr), grouped: c.count > 1}
	peer.setReplyControl(m.OOB[:m.NN])
	n := copy(b, c.data[c.next-1][:min(m.N, len(c.data[0]))])
	return n, peer, nil
}

// Copy a single kernel-provided packet-info header into private storage.
// Only the source-address fields are retained, matching ControlMessage{Src:dst}.
// No interface index or unrelated ancillary message is reflected to the peer.
func (p *udpPacketPeer) setReplyControl(oob []byte) {
	original := oob
	for len(oob) >= unix.CmsgLen(0) {
		h, data, rest, err := unix.ParseOneSocketControlMessage(oob)
		if err != nil {
			break
		}
		size := unix.CmsgSpace(len(data))
		if size <= len(p.control) && size <= len(oob) {
			offset := unix.CmsgLen(0)
			if h.Level == unix.IPPROTO_IP && h.Type == unix.IP_PKTINFO && len(data) == 12 {
				copy(p.control[:], oob[:size])
				clear(p.control[offset : offset+12])
				copy(p.control[offset+4:offset+8], data[8:12])
				p.replyControl = p.control[:size]
				return
			}
			if h.Level == unix.IPPROTO_IPV6 && h.Type == unix.IPV6_PKTINFO && len(data) == 20 && net.IP(data[:16]).To4() == nil {
				copy(p.control[:], oob[:size])
				clear(p.control[offset+16 : offset+20])
				p.replyControl = p.control[:size]
				return
			}
		}
		oob = rest
	}
	p.replyControl = replyUDPControl(original)
}

func replyUDPControl(oob []byte) []byte {
	var v6 ipv6.ControlMessage
	if v6.Parse(oob) == nil && v6.Dst != nil && v6.Dst.To4() == nil {
		return (&ipv6.ControlMessage{Src: v6.Dst}).Marshal()
	}
	var v4 ipv4.ControlMessage
	if v4.Parse(oob) == nil && v4.Dst != nil {
		return (&ipv4.ControlMessage{Src: v4.Dst}).Marshal()
	}
	// Dual-stack sockets can report an IPv4-mapped destination in IPV6_PKTINFO.
	if v6.Dst != nil && v6.Dst.To4() != nil {
		return (&ipv4.ControlMessage{Src: v6.Dst.To4()}).Marshal()
	}
	return nil
}

func (c *batchUDPConn) WriteTo(b []byte, addr net.Addr) (int, error) {
	if peer, ok := addr.(*udpPacketPeer); ok {
		if peer.grouped {
			return c.writeQueued(b, peer)
		}
		n, _, err := c.UDPConn.WriteMsgUDP(b, peer.replyControl, peer.addr)
		return n, err
	}
	return c.UDPConn.WriteTo(b, addr)
}

type udpPeerWriter struct {
	dns.ResponseWriter
	peer *udpPacketPeer
}

func (w udpPeerWriter) RemoteAddr() net.Addr { return w.peer.addr }
func udpHandler(handler dns.Handler) dns.Handler {
	return dns.HandlerFunc(func(w dns.ResponseWriter, q *dns.Msg) {
		if peer, ok := w.RemoteAddr().(*udpPacketPeer); ok {
			handler.ServeDNS(udpPeerWriter{w, peer}, q)
			return
		}
		handler.ServeDNS(w, q)
	})
}

