	"net"
	"runtime"
	"time"

	"github.com/miekg/dns"
)

// A backlogged socket must not monopolize the processor while newly created
// request handlers wait to run. Yield every eight reads, without a timer or
// an artificial batching delay. Reads, deadlines and errors remain unchanged.
type scheduledUDPReader struct {
	dns.Reader
	reads uint32
}

func scheduleUDPReader(reader dns.Reader) dns.Reader { return &scheduledUDPReader{Reader: reader} }
func (r *scheduledUDPReader) ReadUDP(conn *net.UDPConn, timeout time.Duration) ([]byte, *dns.SessionUDP, error) {
	r.reads++
	if r.reads%8 == 0 {
		runtime.Gosched()
	}
	return r.Reader.ReadUDP(conn, timeout)
}
func (r *scheduledUDPReader) ReadPacketConn(conn net.PacketConn, timeout time.Duration) ([]byte, net.Addr, error) {
	r.reads++
	if r.reads%8 == 0 {
		runtime.Gosched()
	}
	return r.Reader.(dns.PacketConnReader).ReadPacketConn(conn, timeout)
}

