//go:build linux

// Copyright 2026 Кислов Роман Сергеевич
// SPDX-License-Identifier: Apache-2.0
package transport

import (
	"net"
	"runtime"
	"sync"

	"golang.org/x/net/ipv4"
)

type udpWriteResult struct {
	n   int
	err error
}
type udpWriteRequest struct {
	data []byte
	peer *udpPacketPeer
	done chan udpWriteResult
}

var udpWriteRequests = sync.Pool{New: func() any { return &udpWriteRequest{done: make(chan udpWriteResult, 1)} }}

func (c *batchUDPConn) writeQueued(b []byte, peer *udpPacketPeer) (int, error) {
	job := udpWriteRequests.Get().(*udpWriteRequest)
	job.data, job.peer = b, peer
	c.enqueueMu.RLock()
	if c.closed.Load() {
		c.enqueueMu.RUnlock()
		job.data, job.peer = nil, nil
		udpWriteRequests.Put(job)
		return 0, net.ErrClosed
	}
	c.writerOnce.Do(func() { go c.writeLoop() })
	queued := false
	select {
	case c.writes <- job:
		queued = true
	case <-c.closing:
	}
	c.enqueueMu.RUnlock()
	result := udpWriteResult{err: net.ErrClosed}
	if queued {
		result = <-job.done
	}
	job.data, job.peer = nil, nil
	udpWriteRequests.Put(job)
	return result.n, result.err
}

// A caller retains its bytes until acknowledged. There is no batching timer:
// let runnable handlers enqueue, then send only the packets already waiting.
func (c *batchUDPConn) writeLoop() {
	defer close(c.writerDone)
	var jobs [udpReadBatchSize]*udpWriteRequest
	var messages [udpReadBatchSize]ipv4.Message
	var buffers [udpReadBatchSize][1][]byte
	for i := range messages {
		messages[i].Buffers = buffers[i][:]
	}
	for {
		select {
		case jobs[0] = <-c.writes:
		case <-c.writerStop:
			for {
				select {
				case job := <-c.writes:
					job.done <- udpWriteResult{err: net.ErrClosed}
				default:
					return
				}
			}
		}
		runtime.Gosched()
		n := 1
	gather:
		for n < len(jobs) {
			select {
			case jobs[n] = <-c.writes:
				n++
			default:
				break gather
			}
		}
		for i, job := range jobs[:n] {
			messages[i].Buffers[0] = job.data
			messages[i].Addr = job.peer.addr
			messages[i].OOB = job.peer.replyControl
		}
		sent, _ := c.reader.WriteBatch(messages[:n], 0)
		for i, job := range jobs[:n] {
			result := udpWriteResult{n: len(job.data)}
			if i >= sent {
				// A partial batch can stop at one bad destination. Send each remaining
				// datagram separately so it cannot suppress unrelated valid responses.
				result.n, _, result.err = c.UDPConn.WriteMsgUDP(job.data, job.peer.replyControl, job.peer.addr)
			}
			messages[i].Buffers[0], messages[i].Addr, messages[i].OOB = nil, nil, nil
			jobs[i] = nil
			job.done <- result
		}
	}
}

